func:
// FAILED / ABORTED / LOAD OFFLINE -> needs a person now
const e = msg.payload;
msg.topic = `KH Bench ALERT: ${e.event}`;
msg.priority = "high";
msg.payload = e.text + (e.run && e.run.fail_reason ? `\nReason: ${e.run.fail_reason}` : "");
node.status({fill: "red", shape: "dot", text: `${e.channel || ""} ${e.event}`});
return msg;

// PASSED / ALL DONE -> operator should swap batteries
const e = msg.payload;
msg.topic = e.event === "bench.all_done" ? "KH Bench: all channels done" : `KH Bench: ${e.serial} PASS`;
msg.priority = "normal";
msg.payload = e.text + (e.cert_no ? `\nCert: ${e.cert_no}` : "");
node.status({fill: "green", shape: "dot", text: e.text.slice(0, 40)});
return msg;

// One JSON line per event -> kh-bench-events.jsonl (audit trail outside the bench PC)
msg.payload = JSON.stringify(msg.payload);
return msg;
